param(
 [string]$ProjectPath='C:\Projects\gympro-api',
 [string]$BackupRoot='C:\Projects\gympro-backups',
 [ValidateRange(1024,65534)][int]$Port=3100
)
$ErrorActionPreference='Stop';$exitCode=1;$process=$null;$credential=$null;$folder=$null
$names=@('GYMPRO_E9_PASSWORD','GYMPRO_E9_PROJECT','GYMPRO_E9_PORT','GYMPRO_E9_REPORT','PGPASSWORD','GYMPRO_B8_DB_PASSWORD','DATABASE_URL','AUTH_DATABASE_URL','GYMPRO_DEV_SESSION_WRITES','GYMPRO_DEV_SESSION_CONFIRM')
$previous=@{};foreach($name in $names){$previous[$name]=[Environment]::GetEnvironmentVariable($name,'Process')}
try{
 $node=(Get-Command node.exe -ErrorAction Stop).Source
 if(-not(Test-Path -LiteralPath (Join-Path $ProjectPath 'node_modules\qrcode\package.json'))){throw 'The existing Gym Pro qrcode package was not found. Use the verified project path; no package will be installed.'}
 foreach($p in @($Port,($Port+1))){$probe=[System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback,$p);try{$probe.Start()}catch{throw "Simulator port $p is busy. Close an earlier simulator or choose another -Port."}finally{$probe.Stop()}}
 $folder=Join-Path $BackupRoot ('e9-local-simulator-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'-'+[guid]::NewGuid().ToString('N').Substring(0,6));New-Item -ItemType Directory -Path $folder|Out-Null
 $zip=Join-Path $folder 'simulator.zip';[IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(''))
 $payload=Join-Path $folder 'simulator';Expand-Archive -LiteralPath $zip -DestinationPath $payload
 $env:GYMPRO_E9_PROJECT=$ProjectPath;$env:GYMPRO_E9_PORT=[string]$Port;$env:GYMPRO_E9_REPORT=$folder
 foreach($name in @('PGPASSWORD','GYMPRO_B8_DB_PASSWORD','DATABASE_URL','AUTH_DATABASE_URL','GYMPRO_DEV_SESSION_WRITES','GYMPRO_DEV_SESSION_CONFIRM')){[Environment]::SetEnvironmentVariable($name,$null,'Process')}
 Write-Host 'Checking the standalone simulator. No database connection or application migration.' -ForegroundColor Cyan
 & $node (Join-Path $payload 'selftest.mjs')
 if($LASTEXITCODE -ne 0){throw 'Local simulator self-test failed. Send the first failing check.'}
 $summary=Get-Content (Join-Path $folder 'simulator-selftest.json') -Raw|ConvertFrom-Json
 if($summary.passed -ne $true -or $summary.qrMode -ne 'installed-qrcode' -or @($summary.checks).Count -ne 24){throw 'Self-test summary is incomplete.'}
 $credential=[System.Management.Automation.PSCredential]::new('local-demo',(Read-Host 'Choose simulator password (10 to 256 characters; separate from Gym Pro)' -AsSecureString))
 $password=$credential.GetNetworkCredential().Password
 if($password.Length -lt 10 -or $password.Length -gt 256){throw 'Simulator password must contain 10 to 256 characters.'}
 $env:GYMPRO_E9_PASSWORD=$password;$password=$null
 $entry=Join-Path $payload 'simulator.mjs'
 $process=Start-Process -FilePath $node -ArgumentList ('"'+$entry+'"') -WorkingDirectory $payload -RedirectStandardOutput (Join-Path $folder 'server-output.txt') -RedirectStandardError (Join-Path $folder 'server-error.txt') -PassThru
 Remove-Item Env:\GYMPRO_E9_PASSWORD -ErrorAction SilentlyContinue;$credential=$null
 $ready=$false;for($i=0;$i -lt 40;$i++){if($process.HasExited){throw "Simulator startup failed. Inspect $folder\server-error.txt"};try{Invoke-WebRequest -Uri "http://127.0.0.1:$Port/" -UseBasicParsing -TimeoutSec 2|Out-Null;$ready=$true;break}catch{Start-Sleep -Milliseconds 500}}
 if(-not $ready){throw 'Simulator startup timed out.'}
 Write-Host 'PASS: Local simulator self-tests completed; demo server started.' -ForegroundColor Green
 Write-Host "Open: http://127.0.0.1:$Port/" -ForegroundColor Cyan
 Write-Host 'Use the simulator password you just chose. No email or Gym Pro credentials required.'
 Write-Host 'Test: create 1000.00 MMK demo order, simulate success, then replay the same event.'
 Write-Host 'Create separate orders to test failure and cancellation. All data is simulated and exists only in memory.'
 Write-Host 'DEMO ONLY: QR is not a KBZPay payment QR; no provider connection or ledger write.' -ForegroundColor Yellow
 Write-Host "Reports: $folder"
 Read-Host 'Keep this window open. Press Enter AFTER browser testing to stop and clear the simulator'|Out-Null
 $exitCode=0
}catch{Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red;if($folder){Write-Host "Reports: $folder"}}
finally{
 if($process -and -not $process.HasExited){Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue;Write-Host 'PASS: Simulator stopped; in-memory test orders, events and sessions discarded.' -ForegroundColor Green}
 $credential=$null;$password=$null;foreach($name in $names){[Environment]::SetEnvironmentVariable($name,$previous[$name],'Process')}
}
exit $exitCode
